import math

def is_power_of_5(m):
    if m <= 0:
        return False
    if m == 1:
        # 2^n - 3 = 1 => 2^n = 4 => n=2. But we require n >= 3.
        return False

    # Check if m is divisible by 5 until it's no longer divisible
    while m > 1 and m % 5 == 0:
        m //= 5
    return m == 1

n_values = [11, 15, 19, 23]
results = {}

for n in n_values:
    M = (2**n) - 3
    is_power = is_power_of_5(M)
    results[n] = (M, is_power)

print(results)

def is_power_of_5(n):
    if n <= 0:
        return False
    if n == 1:
        return True

    count = 0
    while n > 1:
        if n % 5 != 0:
            return False
        n //= 5
        count += 1
    return True

N = 2**27 - 3
print(f"N = {N}")
print(f"Is N a power of 5? {is_power_of_5(N)}")
